auto before=encode_common_state(c.state()),before_birth=encode_family_birth(state);const auto rng=c.state().rng.find("world")->state;fail_birth=true;auto refused=fulfill_birth_arrangement(c,interactions,family,catalog,state,meeting,social,history,accepted.value);check(!refused.ok&&saw_newborn,("late gate not reached: "+refused.error.original.code).c_str());check(compare_boundary(before,encode_common_state(c.state())).exact()&&compare_boundary(before_birth,encode_family_birth(state)).exact()&&social.memories.empty()&&meeting.knowledge.empty(),"late failure retained child, accounts, knowledge or RNG");fail_birth=false;
